/* buzz-parse shim: the lexbor amalgamation (generated by the `native` task
 * into native/build/lexbor_single.h) plus a flat bp_* API for jolt.ffi. */

#include <stdlib.h>
#include <string.h>

/* windows.h pulls in COM's `#define interface struct`, which breaks lexbor's
 * parameters named interface. Include it first, lean, and drop the macro;
 * the include guard makes lexbor's own #include <windows.h> a no-op. */
#ifdef _WIN32
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#undef interface
#endif

#include "lexbor_single.h"
#include "buzz_shim.h"

/* --- documents ------------------------------------------------------------ */

void* bp_parse(const char *html)
{
    lxb_html_document_t *doc = lxb_html_document_create();
    if (doc == NULL) return NULL;
    if (lxb_html_document_parse(doc, (const lxb_char_t *) html, strlen(html))
        != LXB_STATUS_OK) {
        lxb_html_document_destroy(doc);
        return NULL;
    }
    return doc;
}

void bp_destroy(void *doc)
{
    if (doc != NULL) lxb_html_document_destroy(doc);
}

void* bp_root(void *doc)
{
    return lxb_dom_interface_node(doc);
}

void* bp_fragment(void *doc, const char *html)
{
    lxb_html_body_element_t *body = lxb_html_document_body_element(doc);
    if (body == NULL) return NULL;
    return lxb_html_document_parse_fragment(doc, lxb_dom_interface_element(body),
                                            (const lxb_char_t *) html,
                                            strlen(html));
}

/* --- navigation ----------------------------------------------------------- */

int bp_type(void *node)
{
    return (int) lxb_dom_interface_node(node)->type;
}

static int is_template(lxb_dom_node_t *n)
{
    return n->type == LXB_DOM_NODE_TYPE_ELEMENT
        && n->local_name == LXB_TAG_TEMPLATE
        && n->ns == LXB_NS_HTML;
}

void* bp_first_child(void *node)
{
    lxb_dom_node_t *n = lxb_dom_interface_node(node);
    if (is_template(n)) {
        lxb_html_template_element_t *t = lxb_html_interface_template(n);
        if (t->content == NULL) return NULL;
        return lxb_dom_interface_node(t->content)->first_child;
    }
    return n->first_child;
}

void* bp_next(void *node)
{
    return lxb_dom_interface_node(node)->next;
}

const char* bp_tag(void *node)
{
    size_t len;
    return (const char *) lxb_dom_element_local_name(
        lxb_dom_interface_element(node), &len);
}

const char* bp_data(void *node)
{
    lxb_dom_character_data_t *cd = lxb_dom_interface_character_data(node);
    return cd->data.data != NULL ? (const char *) cd->data.data : "";
}

/* --- attributes ----------------------------------------------------------- */

void* bp_first_attr(void *node)
{
    return lxb_dom_element_first_attribute(lxb_dom_interface_element(node));
}

void* bp_next_attr(void *attr)
{
    return lxb_dom_element_next_attribute(attr);
}

const char* bp_attr_name(void *attr)
{
    size_t len;
    return (const char *) lxb_dom_attr_qualified_name(attr, &len);
}

const char* bp_attr_value(void *attr)
{
    size_t len;
    const lxb_char_t *v = lxb_dom_attr_value(attr, &len);
    return v != NULL ? (const char *) v : "";
}

/* --- selectors ------------------------------------------------------------ */

typedef struct {
    void   **items;
    int      count;
    int      cap;
    int      failed;
} bp_nodes_t;

static lxb_status_t collect(lxb_dom_node_t *node,
                            lxb_css_selector_specificity_t spec, void *ctx)
{
    (void) spec;
    bp_nodes_t *ns = ctx;
    if (ns->count == ns->cap) {
        int cap = ns->cap ? ns->cap * 2 : 16;
        void **items = realloc(ns->items, sizeof(void *) * cap);
        if (items == NULL) { ns->failed = 1; return LXB_STATUS_ERROR_MEMORY_ALLOCATION; }
        ns->items = items;
        ns->cap = cap;
    }
    ns->items[ns->count++] = node;
    return LXB_STATUS_OK;
}

void* bp_select(void *root, const char *selector)
{
    bp_nodes_t *ns = calloc(1, sizeof(bp_nodes_t));
    lxb_css_parser_t *parser = lxb_css_parser_create();
    lxb_selectors_t *sel = lxb_selectors_create();
    lxb_css_selector_list_t *list = NULL;
    int ok = ns != NULL && parser != NULL && sel != NULL
          && lxb_css_parser_init(parser, NULL) == LXB_STATUS_OK
          && lxb_selectors_init(sel) == LXB_STATUS_OK;

    if (ok) {
        list = lxb_css_selectors_parse(parser, (const lxb_char_t *) selector,
                                       strlen(selector));
        ok = list != NULL && parser->status == LXB_STATUS_OK;
    }
    if (ok) {
        lxb_selectors_opt_set(sel, LXB_SELECTORS_OPT_MATCH_FIRST);
        ok = lxb_selectors_find(sel, lxb_dom_interface_node(root), list,
                                collect, ns) == LXB_STATUS_OK
          && !ns->failed;
    }

    /* teardown order from lexbor's examples/lexbor/selectors/easy_way.c */
    if (sel != NULL) lxb_selectors_destroy(sel, true);
    if (parser != NULL) lxb_css_parser_destroy(parser, true);
    if (list != NULL) lxb_css_selector_list_destroy_memory(list);

    if (!ok) {
        bp_nodes_free(ns);
        return NULL;
    }
    return ns;
}

int bp_nodes_count(void *nodes)
{
    return ((bp_nodes_t *) nodes)->count;
}

void* bp_nodes_get(void *nodes, int i)
{
    bp_nodes_t *ns = nodes;
    return (i >= 0 && i < ns->count) ? ns->items[i] : NULL;
}

void bp_nodes_free(void *nodes)
{
    bp_nodes_t *ns = nodes;
    if (ns == NULL) return;
    free(ns->items);
    free(ns);
}

/* --- serialization -------------------------------------------------------- */

static char* copy_out(const lxb_char_t *data, size_t len)
{
    char *out = malloc(len + 1);
    if (out == NULL) return NULL;
    if (len) memcpy(out, data, len);
    out[len] = '\0';
    return out;
}

typedef lxb_status_t (*serialize_f)(lxb_dom_node_t *, lexbor_str_t *);

static char* serialize(void *node, serialize_f f)
{
    lxb_dom_node_t *n = lxb_dom_interface_node(node);
    lexbor_str_t str = {0};
    char *out = NULL;
    if (f(n, &str) == LXB_STATUS_OK) {
        out = copy_out(str.data, str.length);
    }
    if (str.data != NULL) {
        lexbor_str_destroy(&str, n->owner_document->text, false);
    }
    return out;
}

char* bp_outer_html(void *node)
{
    return serialize(node, lxb_html_serialize_tree_str);
}

char* bp_inner_html(void *node)
{
    return serialize(node, lxb_html_serialize_deep_str);
}

char* bp_text(void *node)
{
    lxb_dom_node_t *n = lxb_dom_interface_node(node);
    size_t len = 0;
    lxb_char_t *t = lxb_dom_node_text_content(n, &len);
    if (t == NULL) return copy_out((const lxb_char_t *) "", 0);
    char *out = copy_out(t, len);
    lxb_dom_document_destroy_text(n->owner_document, t);
    return out;
}

void bp_free(void *p)
{
    free(p);
}
